specific\ndata (news, time entries) stays in the orchestrator — it will move\nwhen those modules become standalone remotes in later steps.","tree":{"sha":"c55744bdf42b6eebf35766cdf77232fd57447d87","url":"https://api.github.com/repos/Krippke/monolith-to-micro-frontends/git/trees/c55744bdf42b6eebf35766cdf77232fd57447d87"},"url":"https://api.github.com/repos/Krippke/monolith-to-micro-frontends/git/commits/5bdedd29383c6113dfa6a58fea19dca504f9c6c9","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/8778337?v=4","events_url":"https://api.github.com/users/Krippke/events{/privacy}","followers_url":"https://api.github.com/users/Krippke/followers","following_url":"https://api.github.com/users/Krippke/following{/other_user}","gists_url":"https://api.github.com/users/Krippke/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/Krippke","id":8778337,"login":"Krippke","node_id":"MDQ6VXNlcjg3NzgzMzc=","organizations_url":"https://api.github.com/users/Krippke/orgs","received_events_url":"https://api.github.com/users/Krippke/received_events","repos_url":"https://api.github.com/users/Krippke/repos","site_admin":false,"starred_url":"https://api.github.com/users/Krippke/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/Krippke/subscriptions","type":"User","url":"https://api.github.com/users/Krippke","user_view_type":"public"},"html_url":"https://github.com/Krippke/monolith-to-micro-frontends/commit/5bdedd29383c6113dfa6a58fea19dca504f9c6c9","node_id":"C_kwDORLnz0doAKDViZGVkZDI5MzgzYzYxMTNkZmE2YTU4ZmVhMTlkY2E1MDRmOWM2Yzk","parents":[{"html_url":"https://github.com/Krippke/monolith-to-micro-frontends/commit/622d68e1a1ab91606ef3755c594b8cfebfac8580","sha":"622d68e1a1ab91606ef3755c594b8cfebfac8580","url":"https://api.github.com/repos/Krippke/monolith-to-micro-frontends/commits/622d68e1a1ab91606ef3755c594b8cfebfac8580"}],"sha":"5bdedd29